import 'package:flutter_test/flutter_test.dart';
import 'package:site_quant/models/masonry_input.dart';
import 'package:site_quant/models/masonry_result.dart';
import 'package:site_quant/models/opening_deduction.dart';
import 'package:site_quant/services/masonry_reference_defaults.dart';
import 'package:site_quant/services/masonry_v2_calculator.dart';
void main(){MasonryInput input(MasonryType type,{double area=10,List<OpeningDeduction> openings=const[]}){final p=MasonryReferenceDefaults.forType(type);return MasonryInput(type:type,grossArea:area,thicknessMm:p.thicknessMm,unitSize:p.unitSize,openings:openings,cementPart:1,sandPart:6,wastagePercent:p.wastagePercent,unitRate:p.unitRate,cementRatePerBag:p.cementRatePerBag,sandRatePerM3:p.sandRatePerM3,masonDaysPerM3:p.masonDaysPerM3,helperDaysPerM3:p.helperDaysPerM3,masonDailyWage:p.masonWage,helperDailyWage:p.helperWage,masons:1,helpers:1);}for(final type in MasonryType.values){test('${type.label} estimate calculates',(){final r=MasonryV2Calculator.calculate(input(type));expect(r.takeoff.unitCount,greaterThan(0));expect(r.materialCost,greaterThan(0));expect(r.totalCost,greaterThan(r.materialCost));});}test('opening deductions reduce net area once',(){final r=MasonryV2Calculator.calculate(input(MasonryType.clayBrick,openings:[const OpeningDeduction(name:'Door',widthMetres:1,heightMetres:2,quantity:1)]));expect(r.area.netArea,8);});test('invalid opening exceeds wall area',(){expect(()=>MasonryV2Calculator.calculate(input(MasonryType.clayBrick,area:1,openings:[const OpeningDeduction(name:'Door',widthMetres:2,heightMetres:2,quantity:1)])),throwsArgumentError);});}
